INSERT INTO grant_programs (program_id, program_code, program_name, category, description, total_budget_inr, allocated_budget_inr, disbursed_budget_inr, min_award_inr, max_award_inr, opens_at, closes_at, status, created_by_user_id) VALUES (5, 'GMS-2024-WAT-005', 'Jal Samrakshan Watershed Mission 2024', 'Water Conservation', 'Community rain-water harvesting structures, rejuvenation of traditional step-wells and percolation ponds in arid and semi-arid talukas.', 60000000, 60000000, 58000000, 2000000, 6000000, '2024-03-01', '2024-09-30', 'CLOSED', 2);
