INSERT INTO grant_programs (program_id, program_code, program_name, category, description, total_budget_inr, allocated_budget_inr, disbursed_budget_inr, min_award_inr, max_award_inr, opens_at, closes_at, status, created_by_user_id) VALUES (11, 'GMS-2026-MAX-011', 'National Inter-Disciplinary Mega-Consortium for Advanced Deep-Tech Infrastructure and High-Performance Resilience Systems across Urban and Rural Ecosystems Scheme of the Government of India Phase IV', 'Deep Tech & Infrastructure', 'This apex national strategic initiative represents a comprehensive, multi-tiered framework specifically architected to provide substantial non-dilutive financial assistance, capital equipment subventions, and technical enablement grants to collaborative consortia comprising accredited academic universities, premier state-funded scientific research laboratories, certified social impact nongovernmental entities, and registered high-technology early-stage commercial ventures. Participating applicant entities must furnish rigorous documentation establishing proven organizational track records of not less than five consecutive fiscal years, substantiated audited financial balance sheets demonstrating compliant statutory accounting adherence under Indian regulatory standards, verified GST and Darpan registration credentials, and detailed project execution milestone roadmaps outlining quantifiable operational deliverables. Priority evaluation weightage is explicitly allocated towards sustainable low-carbon technological methodologies, indigenous intellectual property generation under Make in India guidelines, verifiable socioeconomic empowerment indices for marginalized demographics, scalable decentralized infrastructure deployment architectures, robust data privacy safeguards conforming to digital governance protocols, and verifiable co-financing commitments from accredited industry partners. All grant allocations under this flagship scheme remain subject to stringent tri-annual technical review inspections, third-party performance audit evaluations, and real-time electronic fund tracking via automated public financial management gateways.', 250000000, 0, 0, 10000000, 50000000, '2026-06-01', '2026-12-31', 'DRAFT', 1);
INSERT INTO grant_programs (program_id, program_code, program_name, category, description, total_budget_inr, allocated_budget_inr, disbursed_budget_inr, min_award_inr, max_award_inr, opens_at, closes_at, status, created_by_user_id) VALUES (12, 'GMS-2023-ARC-012', 'Heritage Crafts & Artisans Support Archive', 'Livelihood', 'Archived historical grant round for traditional handloom revival.', 20000000, 20000000, 20000000, 500000, 2000000, '2023-01-01', '2023-08-31', 'ARCHIVED', 2);
